//! acpi.resource's functions: the firmware's namespace - a name found by
//! its path, and the devices gone through. A resource: no Open or Close,
//! its first function in the first slot. The base comes from
//! OpenResource("acpi.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/acpi_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const acpi = @import("../resources/acpi.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "acpi.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const FindAcpiNode = libraries.lvo(0);
    pub const NextAcpiDevice = libraries.lvo(1);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const FindAcpiNode = *const fn (*AcpiBase, ?*acpi.AcpiNode, [*:0]const u8) callconv(.c) ?*acpi.AcpiNode;
    pub const NextAcpiDevice = *const fn (*AcpiBase, ?*acpi.AcpiNode, ?[*:0]const u8) callconv(.c) ?*acpi.AcpiNode;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const AcpiBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *AcpiBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The name at `path` from `scope` (null: the root) - "\\_SB.PCI0",
    /// "PCI0._HID", "^_PRT" - or null where there is none.
    pub fn FindAcpiNode(self: *AcpiBase, scope: ?*acpi.AcpiNode, path: [*:0]const u8) ?*acpi.AcpiNode {
        return libraries.call(self, LVO.FindAcpiNode, Fn.FindAcpiNode, .{ scope, path });
    }

    /// The device after `old` (null: from the start) in the namespace's
    /// order whose identity or compatible identity is `id` ("PNP0C0C"),
    /// every device where `id` is null; null after the last.
    pub fn NextAcpiDevice(self: *AcpiBase, old: ?*acpi.AcpiNode, id: ?[*:0]const u8) ?*acpi.AcpiNode {
        return libraries.call(self, LVO.NextAcpiDevice, Fn.NextAcpiDevice, .{ old, id });
    }
};
